fn capitalize_first_letter(word: Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(word.len());

    if word.is_empty() {
        // Problem states input is non-empty, but just handle this gracefully.
        return result;
    }

    let first_char = word[0];
    // Check if first_char is uppercase A-Z
    if first_char.is_uppercase() {
        // Keep it unchanged
        result.push(first_char);
    } else {
        // Replace with uppercase 'A'
        result.push('A');
    }

    // Append the rest of the characters unchanged
    result.extend_from_slice(&word[1..]);

    result
}